        visitor.style.top = pos.y + 'px';
    }

    // 交互逻辑：点击地图模拟移动
    document.getElementById('map-container').addEventListener('click', (e) => {
        if (currentStep < 2) {
            currentStep++;
            updateUI(currentStep);
        } else {
            currentStep = 0;
            updateUI(0);
        }
    });

    // 初始化
    updateUI(0);
</script>

</body>
