<html lang="zh-CN">
<head>
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'; media-src 'none'; object-src 'none'">
    <meta charset="UTF-8">
    <title>乐高城堡拼搭指南设计</title>
    <style>
        :root { --primary: #4a90e2; --error: #e74c3c; --success: #27ae60; }
        body { font-family: sans-serif; display: flex; flex-direction: column; align-items: center; background: #f4f7f6; margin: 0; padding: 20px; height: 100vh; box-sizing: border-box; }
        .container { width: 800px; height: 600px; background: white; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.1); display: flex; flex-direction: column; padding: 20px; }
        .main-view { display: flex; flex: 1; gap: 20px; }
        .left-panel { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; border-right: 2px dashed #ccc; }
        .right-panel { flex: 2; display: flex; flex-direction: column; gap: 20px; padding: 10px; }
        .slots { display: flex; gap: 15px; justify-content: center; }
        .slot { width: 120px; height: 160px; border: 3px dashed #aaa; border-radius: 8px; display: flex; align-items: center; justify-content: center; position: relative; background: #fafafa; }
        .parts-bin { display: flex; gap: 20px; justify-content: center; padding: 20px; background: #eee; border-radius: 8px; }
        .part { width: 100px; height: 80px; cursor: grab; display: flex; align-items: center; justify-content: center; font-weight: bold; color: white; border-radius: 5px; user-select: none; }
        #part-base { background: #5d4037; }
        #part-wall { background: #7f8c8d; }
        #part-roof { background: #c0392b; }
