        svg { width: 200px; height: 200px; }
    </style>
</head>
<body>

<div class="container">
    <h3>任务：为小弟弟设计一份拼搭指南</h3>
    <div class="main-view">
        <div class="left-panel">
            <p>成品参考图</p>
            <svg id="castle-view" viewBox="0 0 100 100">
                <rect id="v-base" x="20" y="70" width="60" height="20" fill="#ccc" />
                <rect id="v-wall" x="30" y="40" width="40" height="30" fill="#ccc" />
                <polygon id="v-roof" points="25,40 75,40 50,10" fill="#ccc" />
            </svg>
        </div>
        <div class="right-panel">
            <div class="slots">
                <div class="slot" id="s1" data-order="0">步骤 1</div>
                <div class="slot" id="s2" data-order="1">步骤 2</div>
                <div class="slot" id="s3" data-order="2">步骤 3</div>
