            <div class="hint" id="msg"></div>
            <div class="parts-bin">
                <div class="part" id="part-base" draggable="true">底座</div>
                <div class="part" id="part-wall" draggable="true">城墙</div>
                <div class="part" id="part-roof" draggable="true">屋顶</div>
            </div>
        </div>
    </div>
</div>

<script>
    const slots = document.querySelectorAll('.slot');
    const parts = document.querySelectorAll('.part');
    const msg = document.getElementById('msg');
    const state = [null, null, null];

    parts.forEach(p => {
        p.addEventListener('dragstart', e => e.dataTransfer.setData('text', e.target.id));
    });

    slots.forEach(s => {
        s.addEventListener('dragover', e => e.preventDefault());
        s.addEventListener('drop', e => {
            e.preventDefault();
            const partId = e.dataTransfer.getData('text');
            const slotIdx = parseInt(s.id.replace('s', '')) - 1;

            state[slotIdx] = partId;
            s.innerHTML = document.getElementById(partId).innerText;
            checkOrder();
        });
    });

    function checkOrder() {
        const order = ['part-base', 'part-wall', 'part-roof'];
        let error = false;

        // 检查逻辑
        if (state[0] && state[0] !== 'part-base') {
            showError(state[0], "没有底座，无法固定！");
            return;
        }
        if (state[1] && state[1] !== 'part-wall' && state[0] === 'part-base') {
            showError(state[1], "底座之上应先建城墙！");
            return;
        }

        // 成功动画
        if (state.every((val, i) => val === order[i])) {
