            document.getElementById('v-base').style.fill = "#5d4037";
            document.getElementById('v-wall').style.fill = "#7f8c8d";
            document.getElementById('v-roof').style.fill = "#c0392b";
        }
    }

    function showError(id, text) {
        msg.innerText = text;
        const el = document.querySelector(`[data-order="${state.indexOf(id)}"]`);
        el.style.borderColor = "var(--error)";
        setTimeout(() => { el.style.borderColor = "#aaa"; }, 1000);
    }
</script>
</body>
</html>", "visual_aid_urls": [], "priority": 0.65}, {"id": "V1-2", "content": "突然接到通知说教学楼前的路正在施工无法通行，这时候你该怎么修改刚才给家长的指路步骤，才能让他绕开施工区域，依然顺利到达图书馆呢？", "question_type": "variant", "lesson_presentation_script": "计划赶不上变化！刚才我们设计的指路方案非常完美，但突然，学校大屏幕上教学楼前出现了一个“施工禁行”的标志。这时候，原本的第二步“直行经过教学楼”就行不通了。大家别慌，仔细观察地图，看看还有没有别的通道？我们要怎么调整我们的步骤卡片，才能让家长安全绕行，顺利到达图书馆呢？", "explanation": "【参考答案】修改后的步骤应避开施工区域。例如：“第一步：从校门口直行30米到达操场入口；第二步：向左转，沿着操场红跑道外侧的通道直行；第三步：看到红色的图书馆大楼后，从正门走进去。”
【解题思路】考查学生在约束条件改变时，重新规划、调整步骤序列的能力，保持步骤的明确性与连贯性。
【易错点提醒】学生容易在绕行时给出“随便绕一下”等不明确的口头描述，或者忽略了绕行后方向的改变（如原本右转变为左转）。", "knowledge_points": ["KP6"], "cognitive_level": "应用", "difficulty": 0.62, "main_id": "M1", "parent_id": "M1", "variation_type": "", "design_intent": "引入规则限制，促使学生在动态调整中加深对“可行步骤”的理解，避免机械套用固定路线，培养灵活的问题解决能力。", "design_rationale": "", "visual_aid_prompt": "在原校园地图上，教学楼前增加一个闪烁的红色“路障”图标，原本直通的绿色路线在此处断开。交互方式：学生可以拖动“访客小人”尝试新的路线。反馈效果：当小人碰到路障时，会弹出红色警示并退回；当学生点击操场另一侧的绿色虚线通道时，左侧的步骤卡片会动态更新为“绕行操场”，并高亮显示“根据环境变化调整步骤”的字样，让学生直观看到条件变化对步骤设计的影响。", "visual_aid_type": "illustration", "visual_aid_html": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'; media-src 'none'; object-src 'none'">
    <meta charset="UTF-8">
    <title>路径规划：应对施工路障</title>
    <style>
        :root { --primary: #2c3e50; --accent: #27ae60; --danger: #e74c3c; }
        body { font-family: sans-serif; display: flex; flex-direction: column; align-items: center; background: #f4f7f6; margin: 0; padding: 10px; height: 100vh; box-sizing: border-box; }
        #container { width: 80vh; height: 60vh; background: white; border: 2px solid #ddd; position: relative; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.1); }
        .controls { margin-top: 10px; text-align: center; }
        #msg { font-size: 1.2em; color: var(--primary); font-weight: bold; margin-bottom: 5px; }
        .hint { font-size: 0.9em; color: #666; }
        #visitor { cursor: grab; transition: transform 0.1s; }
        .roadblock { animation: blink 1s infinite; }
        @keyframes blink { 50% { opacity: 0.3; } }
    </style>
</head>
<body>

<div id="msg">请拖动“访客”避开路障到达图书馆</div>
<div id="container">
    <svg viewBox="0 0 400 300" width="100%" height="100%">
        <!-- 背景：校园 -->
        <rect x="50" y="50" width="100" height="80" fill="#eee" stroke="#999"/> <!-- 教学楼 -->
        <rect x="250" y="150" width="100" height="100" fill="#d5e8d4" stroke="#82b366"/> <!-- 图书馆 -->
        <rect x="50" y="200" width="150" height="60" fill="#fff2cc" stroke="#d6b656"/> <!-- 操场 -->

        <!-- 路径 -->
        <path id="path-main" d="M 150 90 L 300 90 L 300 150" fill="none" stroke="#27ae60" stroke-width="4" stroke-dasharray="5,5"/>
        <path id="path-alt" d="M 150 230 L 300 230 L 300 250" fill="none" stroke="#27ae60" stroke-width="4" stroke-dasharray="5,5"/>

        <!-- 路障 -->
        <g id="block" class="roadblock">
            <rect x="210" y="80" width="20" height="20" fill="#e74c3c"/>
            <text x="212" y="95" fill="white" font-size="12">X</text>
        </g>

        <!-- 访客 -->
        <circle id="visitor" cx="60" cy="90" r="10" fill="#3498db" />
    </svg>
</div>

<div class="controls">
    <div class="hint" id="status">当前步骤：直行穿过教学楼前广场</div>
</div>

<script>
    const visitor = document.getElementById('visitor');
    const status = document.getElementById('status');
    const container = document.getElementById('container');

    let isDragging = false;

    visitor.addEventListener('mousedown', () => isDragging = true);
    window.addEventListener('mouseup', () => isDragging = false);

    window.addEventListener('mousemove', (e) => {
        if (!isDragging) return;

        const rect = container.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        visitor.setAttribute('cx', x);
        visitor.setAttribute('cy', y);

        // 碰撞检测逻辑
        if (x > 200 && x < 240 && y > 70 && y < 110) {
            alert("警告：前方施工，无法通行！");
            visitor.setAttribute('cx', 60);
            visitor.setAttribute('cy', 90);
        }

        // 到达终点检测
        if (x > 250 && y > 150) {
            if (y > 200) {
                status.innerHTML = "<span style='color:green; font-weight:bold;'>成功！根据环境变化调整步骤：绕行操场，避开施工区。</span>";
            }
        }
    });
</script>
</body>
</html>", "visual_aid_urls": [], "priority": 0.7}, {"id": "V2-1", "content": "逛超市时的购物清单和自助结账机上的扫码结账指南，它们都写在纸上，为什么只有结账指南能被称为算法，而购物清单却不算呢？", "question_type": "variant", "lesson_presentation_script": "看来大家对番茄炒蛋和日记的区别已经很清楚了。那我们再跟着妈妈去一趟超市。这里有两张纸，一张是妈妈写的“购物清单：苹果、牛奶、面包”；另一张是结账机上的“结账指南：第一步扫商品，第二步付钱”。它们都是一行一行的，为什么只有结账指南是算法呢？请大家在小组里争论一下，找出最核心的那个原因！", "explanation": "【参考答案】购物清单只是静态的信息记录，没有先后执行顺序，即使调换顺序也不影响买东西，且它不代表一个操作过程；而结账指南是为了解决“完成付款”这一具体问题，且包含第一步、第二步等不可颠倒的执行步骤，属于解决问题的方法。因此结账指南是算法，购物清单不是。
【解题思路】引导学生抓住“解决问题”和“步骤执行”这两个算法核心要素进行对比，排除格式上的干扰。
【易错点提醒】学生容易产生“只要有一二三序号、写在纸上的就是算法”的误区，需强调算法的“动作性”和“过程性”。", "knowledge_points": ["KP1"], "cognitive_level": "理解", "difficulty": 0.61, "main_id": "M2", "parent_id": "M2", "variation_type": "", "design_intent": "针对学生容易把“任何列表/文字”都当成算法的易错点，通过对比无序的清单和有序的交互步骤，明确算法的“过程性”和“目的性”。", "design_rationale": "", "visual_aid_prompt": "左右并列展示“购物清单（苹果、牙膏、面包）”和“自助结账步骤（1.扫描条码 2.出示付款码 3.打印小票）”。界面中间有一个“模拟执行”按钮。交互方式：学生点击按钮。反馈效果：清单一侧无变化，并弹出提示“清单各项无顺序，无法被机器自动执行”；结账步骤一侧则依次高亮每个步骤，并伴随商品被扫描、扣款成功的动画，通过动态执行过程，让学生一眼看出“算法是可以一步步运转以解决问题的方法”。", "visual_aid_type": "diagram", "visual_aid_html": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'; media-src 'none'; object-src 'none'">
    <meta charset="UTF-8">
    <title>算法与清单的区别</title>
    <style>
        :root { --primary: #2563eb; --bg: #f8fafc; }
        body { font-family: sans-serif; background: var(--bg); display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100vh; margin: 0; }
        .container { width: 90%; max-width: 800px; background: white; padding: 20px; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
        .panels { display: flex; justify-content: space-between; gap: 20px; margin-bottom: 20px; }
        .panel { flex: 1; border: 2px solid #e2e8f0; padding: 15px; border-radius: 8px; }
        h3 { margin-top: 0; color: #1e293b; text-align: center; }
        .item { padding: 8px; margin: 5px 0; background: #f1f5f9; border-radius: 4px; transition: 0.3s; }
        .active { background: #dbeafe; border-left: 4px solid var(--primary); }
        #control-btn { display: block; width: 200px; margin: 0 auto; padding: 10px; background: var(--primary); color: white; border: none; border-radius: 6px; cursor: pointer; font-size: 16px; }
        #message { text-align: center; margin-top: 15px; height: 24px; font-weight: bold; color: #ef4444; }
        .anim-area { height: 60px; display: flex; align-items: center; justify-content: center; gap: 10px; }
        .icon { font-size: 24px; opacity: 0; transition: 0.5s; }
    </style>
</head>
<body>

<div class="container">
    <h3>算法 vs 清单：为什么不一样？</h3>
    <div class="panels">
        <div class="panel" id="list-panel">
            <h3>购物清单</h3>
            <div class="item">1. 苹果</div>
            <div class="item">2. 牙膏</div>
            <div class="item">3. 面包</div>
        </div>
        <div class="panel" id="algo-panel">
            <h3>结账指南</h3>
            <div class="item step">1. 扫描条码</div>
            <div class="item step">2. 出示付款码</div>
            <div class="item step">3. 打印小票</div>
        </div>
    </div>

    <button id="control-btn">开始模拟执行</button>
    <div id="message"></div>

    <div class="anim-area">
        <span id="icon-scan" class="icon">🛒</span>
        <span id="icon-pay" class="icon">💳</span>
        <span id="icon-receipt" class="icon">🧾</span>
    </div>
</div>

<script>
    const btn = document.getElementById('control-btn');
    const steps = document.querySelectorAll('.step');
    const msg = document.getElementById('message');
    const icons = [document.getElementById('icon-scan'), document.getElementById('icon-pay'), document.getElementById('icon-receipt')];
    let running = false;

    btn.addEventListener('click', () => {
        if (running) return;
        running = true;
        msg.textContent = "";
        steps.forEach(s => s.classList.remove('active'));
        icons.forEach(i => i.style.opacity = '0');

        // 模拟清单侧反馈
        setTimeout(() => {
            msg.textContent = "清单：各项无顺序，机器无法自动执行！";
        }, 500);

        // 模拟算法侧执行
        let i = 0;
        const timer = setInterval(() => {
            if (i < steps.length) {
                steps[i].classList.add('active');
                icons[i].style.opacity = '1';
                i++;
            } else {
                clearInterval(timer);
                msg.textContent = "结账完成！算法是有序的执行过程。";
                running = false;
            }
        }, 1000);
    });
</script>

</body>
</html>", "visual_aid_urls": [], "priority": 0.72}, {"id": "V2-2", "content": "教室墙上的电灯开关上写着“按下去灯亮，再按一下灯灭”。这只有一句话，它能算是一个算法吗？请结合算法的定义谈谈你的看法。", "question_type": "variant", "lesson_presentation_script": "大家刚才说，算法得有一步步的步骤。那老师要考考大家了：我们教室的开关，上面写着“按下去灯亮，再按一下灯灭”。这只有简单的一个动作和对应的结果，它能算是一个“算法”吗？它有没有要解决的问题？有没有步骤？千万不要被字数少给迷惑了哦！", "explanation": "【参考答案】它算是一个极简的算法。因为它解决了“如何控制灯的亮灭”这一具体问题，并且包含了“判断当前状态 -> 做出按键动作 -> 改变灯的状态”的逻辑步骤。虽然表述极简，但它完全符合算法是解决问题的方法和步骤这一本质。
【解题思路】引导学生透过简单的表象，分析其背后隐藏的“输入-处理-输出”逻辑，理解算法的本质在于逻辑而非篇幅。
【易错点提醒】学生可能简单地以字数或步骤多少来判定，认为“一步不算算法”，需要引导他们看其是否具备解决问题的逻辑机制。", "knowledge_points": ["KP1"], "cognitive_level": "理解", "difficulty": 0.64, "main_id": "M2", "parent_id": "M2", "variation_type": "", "design_intent": "通过处于边界的模糊案例（极其简单的单步操作），打破学生“算法必须非常复杂、有很多步”的刻板印象，深入理解算法的逻辑本质。", "design_rationale": "", "visual_aid_prompt": "展示一个物理开关和一盏灯。下方有一个隐藏的“逻辑拆解器”框。交互方式：学生点击开关，灯亮/灭。点击“拆解背后的逻辑”按钮。反馈效果：开关内部会弹出一个流程图：“检测当前状态（灭）”->“按下开关（输入）”->“切换为相反状态（处理）”->“灯亮（输出）”，通过将极简动作拆解为标准逻辑，直观展示即使是单一步骤也包含着算法的本质要素。", "visual_aid_type": "diagram", "visual_aid_html": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'; media-src 'none'; object-src 'none'">
    <meta charset="UTF-8">
    <title>算法逻辑可视化 - V2-2</title>
    <style>
        :root { --primary: #2563eb; --bg: #f8fafc; }
        body { font-family: sans-serif; background: var(--bg); display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100vh; margin: 0; overflow: hidden; }
