        .switch { width: 60px; height: 100px; background: #64748b; border-radius: 8px; cursor: pointer; display: flex; flex-direction: column; align-items: center; justify-content: center; color: white; font-weight: bold; }
        #logic-panel { display: none; background: #f1f5f9; padding: 15px; border-radius: 8px; }
        .step { display: inline-block; padding: 8px; margin: 5px; background: white; border: 1px solid #cbd5e1; border-radius: 4px; font-size: 0.9em; }
        button { padding: 10px 20px; background: var(--primary); color: white; border: none; border-radius: 6px; cursor: pointer; font-size: 1em; }
        h2 { margin-top: 0; color: #1e293b; }
    </style>
</head>
<body>

<div id="container">
    <h2>算法逻辑探究：开关的秘密</h2>
