<body>

<div id="stage">
    <div class="sentence">
        倒入 <span class="slot" id="slot1"></span> 的热水，静置 <span class="slot" id="slot2"></span>。
    </div>

    <div class="cards-container">
        <div class="card" id="card1" draggable="true">85℃</div>
        <div class="card" id="card2" draggable="true">3分钟</div>
    </div>

    <div id="robot">🤖</div>
    <div id="message">恭喜！你已成功设计出一条高品质的合格算法步骤！</div>
</div>

<script>
    const slots = document.querySelectorAll('.slot');
    const cards = document.querySelectorAll('.card');
    const robot = document.getElementById('robot');
    const message = document.getElementById('message');
    let filledCount = 0;

    cards.forEach(card => {
        card.addEventListener('dragstart', (e) => {
            e.dataTransfer.setData('text/plain', e.target.id);
        });
    });

    slots.forEach(slot => {
        slot.addEventListener('dragover', (e) => e.preventDefault());
        slot.addEventListener('drop', (e) => {
            e.preventDefault();
            const cardId = e.dataTransfer.getData('text/plain');
            const card = document.getElementById(cardId);

            // 简单的逻辑校验：85℃对应slot1，3分钟对应slot2
            if ((slot.id === 'slot1' && cardId === 'card1') || 
                (slot.id === 'slot2' && cardId === 'card2')) {

                slot.textContent = card.textContent;
                slot.classList.add('filled');
                card.style.visibility = 'hidden';
                filledCount++;

                if (filledCount === 2) {
                    completeTask();
                }
            }
        });
    });

    function completeTask() {
        document.querySelector('.sentence').style.color = '#d4af37';
        robot.style.opacity = '1';
        message.style.visibility = 'visible';

        // 模拟音效反馈
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = audioCtx.createOscillator();
        osc.connect(audioCtx.destination);
        osc.frequency.value = 880;
        osc.start();
        osc.stop(audioCtx.currentTime + 0.2);
    }
</script>

</body>
